      if(foreignSold)f.price*=1-Math.min(.08,foreignSold/votingShares(f)*.8);
      f.price=Math.max(.0001,Math.min(p0*1.1,Math.max(p0*.9,f.price)));f.peak=Math.max((f.peak||f.price)*.999,f.price);f.volume=volume;
