  function mSfx(G,era,tier){tier=tier||0;const r=regime();if(r==='mon'&&era<2)return['','사','감'][tier];const t=TSFX[r]||TSFX.rep;if(r==='com'&&tier===0&&G.minSfx==='인민위원회')return'인민위원회';return t[tier]}
