  function attract(x){return Math.log(Math.max(0,W(x))+10)+x.health/50-x.caught*.6+(x.home?.5:0)+Math.min(1,(x.inv.jewel||0)*.3)+Math.min(.4,(x.inv.cloth||0)*.2)+Math.min(.4,(x.inv.furn||0)*.2)-rumorOf(x)*2}
