    for(const a of S.agents)if(a.alive&&isAdult(a))a.cash=Math.round((20+wr()*180)*(S.mlvl||1));c=S.agents.filter(a=>a.alive&&isAdult(a)).sort((x,y)=>dynScore(y)-dynScore(x)||x.id-y.id)[0];Object.assign(S.dyn,{pid:c.id,founder:c.id,house:c.sur+'씨 가문',peak:{w:W(c),title:''}});
