    if(c.sex!=null&&!['M','F'].includes(c.sex))throw Error('성별 값이 올바르지 않습니다');if(age!=null&&(!Number.isInteger(age)||age<18||age>45))throw Error('시작 나이는 18~45세로 정해 주세요');
    if(edu!=null&&(!Number.isInteger(edu)||edu<0||edu>4))throw Error('학력 값이 올바르지 않습니다');if(looks!=null&&(!Number.isFinite(looks)||looks<0||looks>100))throw Error('외모 값은 0~100 사이여야 합니다');
    const traits={},skills={farm:FARM,craft:CRAFT,build:BUILD,trade:TRADE,teach:TEACH,chop:CHOP,mine:MINE};
    for(const k of ['boss','civic','care','cheat','join','lux','roma','faith'])if(c[k]!=null){const n=Number(c[k]);if(!Number.isFinite(n)||n<0||n>100)throw Error('성격 값은 0~100 사이여야 합니다');traits[k]=n/100}
    const skillVals={};for(const[k,id]of Object.entries(skills))if(c[k]!=null){const n=Number(c[k]);if(!Number.isFinite(n)||n<0||n>100)throw Error('기술 값은 0~100 사이여야 합니다');skillVals[id]=n/100}
    const bg=txt(c.background,24),family=c.family||'keep',wealth=c.wealth||'keep',served=c.served||'no',status=c.status||'common';if(!['common','king','tycoon'].includes(status))throw Error('시작 지위를 다시 선택해 주세요');if(!['yes','no'].includes(served))throw Error('병역 여부를 다시 선택해 주세요');if(bg&&!['평범한 주민','농촌','장터','기술자 집안','유학 경험','이주민','정보기관 직원','몰락한 왕족','성직자 집안'].includes(bg))throw Error('출신 배경을 다시 선택해 주세요');
    if(!['keep','single','partner','children'].includes(family)||!['keep','poor','modest','wealthy'].includes(wealth))throw Error('가족이나 시작 재산 조건을 다시 선택해 주세요');
    // 꾸미기 시작은 항상 새 인물이 마을로 이주해 오는 것으로 만든다(기존 주민은 건드리지 않는다).
    // 다시 꾸미면 앞서 만든 인물과 가족을 지우고 새로 만든다. 시작 선택 전에는 시간이 멈춰 있어 다른 주민과 엮이지 않는다.
    if(D.startGovMade){S.gov=null;D.startGovMade=0}
    if(D.startMade){const ids=new Set(D.startMade);for(let i=S.agents.length-1;i>=0;i--)if(ids.has(S.agents[i].id))S.agents.splice(i,1);for(const id of ids)S.byId.delete(id);if(S.yr)S.yr.migIn=Math.max(0,(S.yr.migIn||0)-ids.size);D.startMade=null;dynKinD=-1}
    const wage=Math.max(.5,S.wageAvg||1),mlv=S.mlvl||1,ageY=age!=null?age:20+Math.floor(wr()*11),sex=c.sex||(wr()<.5?'M':'F');
    // 시작 재산은 마을 어른 현금의 중간값(보통 사람)과 집값을 기준으로 정한다(초반 품삯 기준이면 너무 적게 나옴)
    const cs=adultsC().map(x=>x.cash).sort((x,y)=>x-y),med=Math.max(10*mlv,cs[cs.length>>1]||30*mlv),hr0=S.houseRef||100;
    const cash=wealth==='poor'?med*(.3+wr()*.3):wealth==='modest'?med*(1.2+wr()*.6):wealth==='wealthy'?med*3+hr0*(1+wr()):med;
    const a=mk({age:ageY*YEAR,born:S.day-ageY*YEAR,cash,g:randGenome(),migrant:true,sex});a.inv.grain=6;for(const k of PROD)a.skill[k]=.05+wr()*.25;initQ(a);a.edu=edu!=null?edu:0;
    const made=[a.id];
    if(looks!=null){a.g.face=a.g.body=looks/100;a.looks=looks/100;a.faceL=a.bodyL=a.looks}
    for(const[k,v]of Object.entries(traits))a.g[k]=v;for(const[id,v]of Object.entries(skillVals)){a.skill[id]=v;for(const q of a.q)q[id]=Math.max(q[id]||0,v*5)}
    if(sur)a.sur=sur;if(given)a.given=given;
    if(family==='partner'||family==='children'){a.orient='het';const py=cl(ageY+Math.round((wr()-.5)*6),18,60);
      const b=mk({age:py*YEAR,born:S.day-py*YEAR,cash:med*.5,g:randGenome(),migrant:true,sex:a.sex==='M'?'F':'M'});b.orient='het';b.inv.grain=4;for(const k of PROD)b.skill[k]=.05+wr()*.25;initQ(b);b.edu=Math.floor(wr()*2);made.push(b.id);dynWed(a,b);
      if(family==='children'){const n=wr()<.5?2:1,maxY=Math.max(0,Math.min(12,Math.min(ageY,py)-18));
        for(let i=0;i<n;i++){const kd=Math.floor(wr()*(maxY+1))*YEAR+Math.floor(wr()*YEAR*.9);
          const k=mk({sur:a.sur,family:a.family,g:childGenome(a.g,b.g),gen:Math.max(a.gen,b.gen)+1,parents:[a.id,b.id],age:kd,born:S.day-kd,migrant:true});
          for(const s of[0,1])for(let j=0;j<NA;j++)k.q[s][j]=(a.q[s][j]+b.q[s][j])/2*.6+(PROD.includes(j)?1.5:0);for(const j of PROD)k.skill[j]=.05+(a.skill[j]+b.skill[j])*.1;
          a.kids.push(k.id);b.kids.push(k.id);made.push(k.id)}}}
    D.startMade=made;
    // 시작 지위: 갑부는 마을 어른 현금 합계의 4분의 1 + 집 다섯 채 값, 왕은 군주정을 세우고 왕좌에 앉는다
    if(status==='tycoon'){const tot=cs.reduce((t,v)=>t+v,0);a.cash=Math.max(a.cash,tot*.25+hr0*5)}
    if(status==='king'){a.cash=Math.max(a.cash,med*5);a.dynRoyal=2;a.rep=cl((a.rep??.6)+.1,0,1);crownLord(a,'옛 왕가의 핏줄을 내세워',adultsC());D.startGovMade=1}
    // 군필: 징병 대상에서 빠지고 경계심·체력이 조금 오른다(군·정보기관 진로에 유리). 미필이면 징병제가 있을 때 영장이 나올 수 있다.
    if(served==='yes'){a.served=1;a.g.vigil=cl((a.g.vigil??.5)+.06,0,1);a.fit=cl((a.fit??.5)+.05,0,1)}
    if(bg==='농촌')a.skill[FARM]=cl(a.skill[FARM]+.08,0,1);else if(bg==='장터')a.skill[TRADE]=cl(a.skill[TRADE]+.08,0,1);
    else if(bg==='기술자 집안')a.skill[CRAFT]=cl(a.skill[CRAFT]+.08,0,1);else if(bg==='유학 경험'){a.edu=Math.max(a.edu||0,2);a.skill[TEACH]=cl(a.skill[TEACH]+.06,0,1)}else if(bg==='이주민')a.g.explore=cl((a.g.explore||.5)+.08,0,1);else if(bg==='정보기관 직원'){a.g.vigil=cl((a.g.vigil||.5)+.18,0,1);a.g.civic=cl((a.g.civic||.5)+.06,0,1);a.edu=Math.max(a.edu||0,1);D.spyCareer='staff';D.spyExperience=0}
    else if(bg==='몰락한 왕족'){a.dynRoyal=1;a.edu=Math.max(a.edu||0,2);a.g.boss=cl((a.g.boss??.3)+.05,0,1);a.rep=cl((a.rep??.6)+.1,0,1)}
    else if(bg==='성직자 집안'){a.g.faith=cl((a.g.faith??.4)+.15,0,1);a.edu=Math.max(a.edu||0,1);const big=(S.faiths||[]).slice().sort((x,y)=>(y.members||0)-(x.members||0))[0];if(big){a.faith=big.id;D.clergy={...D.clergy,[a.id]:big.id}}}
    D.pid=a.id;D.background=bg==='정보기관 직원'?'정보기관 출신':bg||'평범한 주민';D.familyStart=family;D.wealthStart=wealth;D.servedStart=served;D.statusStart=status;D.customized=true;D.houseAuto=true;D.house=a.sur+'씨 가문';D.founder=a.id;D.peak={w:W(a),title:''};
