      if(G&&wr()<.08){G.approval=Math.max(0,(G.approval??.5)-.02);log('pol',`세금 거부. ${fa.name} 신도들이 "악마의 돈"으로 세금을 낼 수 없다며 버틴다`,[fa.leader])}
