      if(k==='bribe'){const b=Math.min(ctx.b||0,Math.max(0,d.cash));d.cash-=b;me.cash+=b;c.dynD='drop';if(G&&wr()<.2){G.cases.push({t:'bribe',who:me.id,amt:b,ev:.6,d:S.day});return '뇌물을 받고 덮었지만 감찰에 걸렸다'}return `${won(b)}을 받고 사건을 덮었다`}
