      {const D=S.dyn,h=D.storyHist?.[e.id];D.storyHist={...D.storyHist,[e.id]:{k,d:S.day,n:(h?.n||0)+1,ks:[...new Set([...(h?.ks||[]),k])].slice(-6)}}}
      if(e.special){const D=S.dyn;D.specials=[...(D.specials||[]),{d:S.day,gen:D.gen,title:e.title,choice:o[1],res:r}].slice(-60)}
