  function dynOrphans(me){const by=id=>S.byId.get(id);return S.agents.filter(k=>k.alive&&k.age>=YEAR&&k.age<14*YEAR&&!me.kids.includes(k.id)&&!k.parents.some(p=>{const x=by(p);return x&&x.alive})).sort((x,y)=>y.age-x.age)}
