  E('wfHostageRescue',{cat:'외교',need:c=>!!wfHeld(c),title:'🌙 인질 구출의 소문',text:()=>'이웃 왕실이 인질을 몰래 데려갈 준비를 한다는 보고가 올라왔습니다.',o:[['negotiate','석방 협상으로 전환한다','',c=>{const h=wfHeld(c);if(!h)return '인질은 이미 떠났다';return wfAct(c.me,`wf:hostage:${h.id}:ransom`)}],['release','안전한 귀환을 보장한다','',c=>{const h=wfHeld(c);if(!h)return '인질은 이미 떠났다';return wfAct(c.me,`wf:hostage:${h.id}:release`)}]]});
  E('wfProvinceAshes',{cat:'전쟁',need:c=>p2Ruler(c.me)&&dynTowns().some(t=>S.dyn.realms?.[t.name]?.prov?.repression!=null),title:'🕯️ 진압 뒤의 속령',text:()=>'속령의 대표들이 진압 피해를 조사하고 유족을 지원해 달라고 요구합니다.',o:[['repair','지원과 조사를 시작한다','개인 자금 지출',c=>{wfPay(c.me,c.wA*15);for(const t of dynTowns()){const R0=S.dyn.realms?.[t.name];if(R0?.prov?.repression!=null){wfMark(t.name,-.25);R0.prov.unrest=Math.max(0,R0.prov.unrest-.1)}}return '지원과 조사를 시작했다'}],['refuse','요구를 거절한다','속령 불만 상승',c=>{for(const R0 of Object.values(S.dyn.realms||{}))if(R0.prov?.repression!=null)R0.prov.unrest=cl(R0.prov.unrest+.1,0,1);return '대표들이 분노한 채 돌아갔다'},{trait:'care'}]]});
  E('wfPoisonWitness',{cat:'가문',need:c=>wfState().poisons.some(p=>p.by===c.me.id&&!p.exposed),title:'🕵️ 독살의 목격자',text:()=>'가족의 죽음에 의문을 품은 사람이 당시의 증언을 모으고 있습니다.',o:[['confess','음모를 인정한다','살인 수사',c=>{const p=wfState().poisons.find(p=>p.by===c.me.id&&!p.exposed);if(p)p.exposed=true;fileC('murder',c.me,c.wA*12,.9);c.rep(-.15);return '음모를 인정했고 수사가 시작됐다'}],['deny','의혹을 부인한다','증거가 모이면 수사',c=>{if(c.roll(.6)){fileC('murder',c.me,c.wA*12,.65);c.rep(-.1);return '증언이 맞물려 수사로 이어졌다'}return '이번에는 증거가 모이지 않았다'},{trait:'honesty'}]]});
  E('wfInheritanceFeud',{cat:'가문',need:c=>wfState().poisons.some(p=>p.by===c.me.id&&p.success),who:c=>wfKinTargets(c.me)[0],title:'⚖️ 바뀐 상속 순서',text:c=>`${c.n(c.x)}이 갑작스럽게 바뀐 상속 순서에 의문을 제기합니다.`,o:[['open','가문 장부와 상속 계획을 공개한다','',c=>{c.tie(c.x,.15,'상속 설명');return '상속 계획을 공개했지만 의심이 모두 사라지지는 않았다'}],['silence','설명을 거부한다','가족 관계 악화',c=>{c.tie(c.x,-.2,'상속 다툼');return '가족 간 불신이 깊어졌다'}]]});
  E('wfMarriageFlight',{cat:'가문',need:c=>(c.me.kids||[]).some(id=>{const x=sBy(id);return wfAdult(x)&&x.dynEstrangedUntil>S.day}),who:c=>(c.me.kids||[]).map(sBy).find(x=>wfAdult(x)&&x.dynEstrangedUntil>S.day),title:'🧳 혼담을 거부한 자녀',text:c=>`${c.n(c.x)}이 강요한 혼담 때문에 따로 살겠다고 짐을 쌉니다.`,o:[['respect','뜻을 존중하고 독립을 돕는다','생활비 지원',c=>{const amount=Math.min(Math.max(0,c.me.cash),c.wA*5);c.me.cash-=amount;if(c.x){c.x.cash+=amount;c.x.dynEstrangedUntil=0}c.tie(c.x,.2,'화해');return '독립을 지원하며 화해했다'}],['argue','집안의 의무를 강조한다','관계 악화',c=>{c.tie(c.x,-.2,'혼인 강요');if(c.x){const host=adA().find(x=>x!==c.me&&x!==c.x&&x.home);if(host)c.x.home=host.home}return '자녀가 집을 떠나 다른 거처를 구했다'}]]});
  E('wfSecretSupport',{cat:'가문',need:c=>(c.me.secretKids||[]).some(id=>sBy(id)?.dynSecretSupport!=null),title:'📦 조용한 안부',text:()=>'몰래 지원해 온 자식에게서 생활을 꾸려 가고 있다는 안부가 전해졌습니다.',o:[['continue','생활 지원을 이어간다','',c=>{const x=(c.me.secretKids||[]).map(sBy).find(x=>x?.alive);if(!x)return '이미 다른 곳에서 살고 있다';return wfAct(c.me,`wf:secret:${x.id}:support`)}],['letter','답장을 보낸다','',c=>{c.happy(.03);return '안부를 묻는 답장을 보냈다'}]]});
  E('wfGuardianThanks',{cat:'가문',need:c=>(c.me.secretKids||[]).some(id=>sBy(id)?.dynGuardian),title:'🏠 새 거처에서 온 소식',text:()=>'별도 거처에서 지내는 자식의 보호자가 아이의 근황과 생활비 내역을 보내왔습니다.',o:[['visit','찾아가 안부를 살핀다','',c=>{c.happy(.04);return '거처를 찾아 생활을 살피고 돌아왔다'}],['support','추가 생활비를 보낸다','',c=>{const x=(c.me.secretKids||[]).map(sBy).find(x=>x?.alive&&x.dynGuardian);if(!x)return '거처가 바뀌었다';return wfAct(c.me,`wf:secret:${x.id}:support`)}]]});

  // 용병 회사 이야기: 계약·인물·전쟁 상태에 맞는 사건과 연쇄.
  function mcEF(c,p=()=>true){const own=mcMine(c.me);return (c.ctx.firm?own.filter(f=>f.id===c.ctx.firm):own).find(p)}
  const mcActive=f=>f.merc.contract?.status==='active';
  const mcQuiet=f=>!mcActive(f);
  function mcEventPay(c,f,n){if(!f)return false;if(f.cash<n)return false;coSpend(f,n);return true}
  E('mcVeteran',{cat:'용병',need:c=>!!mcEF(c,f=>mcQuiet(f)&&mcMembers(f).length<30)&&mcCandidates(c.me).length>0,title:'🪖 노련한 지원자',text:()=>'먼 전장에서 돌아온 성인 지원자가 계약 조건과 밀린 급여가 없는지 꼼꼼히 묻습니다.',o:[['hire','정식 계약으로 모집한다','회사 계약금 지출',c=>{const f=mcEF(c,mcQuiet),x=mcCandidates(c.me)[0];if(!f||!x)return '지원자가 다른 길을 택했다';return mcAct(c.me,`merc:recruit:${f.id}:p${x.id}`)}],['wait','이번에는 모집하지 않는다','',()=> '지원자에게 결정을 전했다']]});
  E('mcUrgentOffer',{cat:'용병',need:c=>!!mcEF(c,f=>mcQuiet(f)&&mcReady(f).length>0)&&farAlive().some(F=>F.war),title:'📜 급한 해외 계약',text:()=>'전쟁 중인 나라의 사절이 급히 부대를 보내 달라며 계약을 들고 찾아왔습니다. 서명하면 바로 파견됩니다.',o:[['accept','조건을 확인하고 방어 계약을 맺는다','회사에 선금 · 파견 위험',c=>{const f=mcEF(c,f=>mcQuiet(f)&&mcReady(f).length>0),F=farAlive().find(F=>F.war);if(!f||!F)return '계약할 전쟁이 끝났다';return mcAct(c.me,`merc:contract:${f.id}:${encodeURIComponent(F.name)}:defend`)}],['decline','위험을 보고 거절한다','',()=> '이번 계약을 거절했다']]});
  E('mcLatePay',{cat:'용병',need:c=>!!mcEF(c,f=>mcActive(f)&&f.merc.contract.arrears>0),title:'💸 고용국의 체불',text:()=>'약속한 보수가 도착하지 않았습니다. 지휘관은 회사 자금으로 버틸지 철수할지 지시를 기다립니다.',o:[['wait','계약을 유지하며 기다린다','회사 사기 하락',c=>{const f=mcEF(c,mcActive);if(f)f.merc.morale=Math.max(0,f.merc.morale-.05);return '체불 보수를 장부에 남기고 계약을 유지했다'}],['leave','철수한다','미수금 포기·신용 하락',c=>{const f=mcEF(c,mcActive);if(!f)return '계약이 이미 끝났다';mcFinish(f,'withdraw');return '철수 명령을 내렸다'}]]});
  E('mcEncircled',{cat:'용병',need:c=>!!mcEF(c,mcActive),title:'🏴 고립된 부대',text:()=>'전선에서 연락이 끊겼다가 다시 이어졌습니다. 부대가 고립되어 보급과 철수 지원을 요청합니다.',o:[['relief','회사 자금으로 구호·보급을 보낸다','회사 비용',c=>{const f=mcEF(c,mcActive);if(!f)return '부대가 이미 돌아왔다';if(!mcEventPay(c,f,c.wA*12))return '회사 자금이 부족해 보급을 보내지 못했다';f.merc.fatigue=Math.max(0,f.merc.fatigue-.15);c.chain('mcReturn',10,{firm:f.id});return '보급을 보내고 생환 연락을 기다린다'}],['withdraw','계약을 끝내고 철수한다','',c=>{const f=mcEF(c,mcActive);if(f)mcFinish(f,'withdraw');return '부대에 철수를 명령했다'}]]});
  E('mcReturn',{cat:'용병',chain:1,title:'⛵ 부대의 생환 소식',text:()=>'고립됐던 부대가 보급로를 따라 안전한 주둔지에 도착했다는 연락이 왔습니다.',o:[['rest','휴식과 치료를 보장한다','회사 비용·건강 회복',c=>{const f=mcEF(c);if(!f)return '회사는 이미 정리됐다';return mcAct(c.me,`merc:heal:${f.id}`)}],['praise','공로를 인정한다','사기 상승',c=>{const f=mcEF(c);if(f)f.merc.morale=cl(f.merc.morale+.08,0,1);return '대원들의 공로를 공개적으로 인정했다'}]]});
  E('mcCaptiveCommander',{cat:'용병',need:c=>!!mcEF(c,f=>mcMembers(f).some(x=>x.dynMercCaptive)),title:'🔒 붙잡힌 대원',text:()=>'포로가 된 대원들의 안부와 귀환 조건이 전달됐습니다. 가족들도 회사의 결정을 기다리고 있습니다.',o:[['ransom','회사 자금으로 귀환 협상한다','몸값 지출',c=>{const f=mcEF(c,f=>mcMembers(f).some(x=>x.dynMercCaptive));if(!f)return '포로들이 이미 돌아왔다';return mcAct(c.me,`merc:ransom:${f.id}`)}],['wait','자금을 마련하며 협상을 이어간다','',()=> '귀환을 위한 협상을 계속한다']]});
  E('mcTired',{cat:'용병',need:c=>!!mcEF(c,f=>mcActive(f)&&f.merc.fatigue>.3),title:'🥾 끝나지 않는 파견',text:()=>'오랜 파견으로 대원들의 피로가 쌓였습니다. 지휘관이 더는 같은 전력을 기대하기 어렵다고 보고합니다.',o:[['care','치료와 휴식을 지원한다','회사 비용',c=>{const f=mcEF(c,mcActive);if(!f)return '파견이 끝났다';return mcAct(c.me,`merc:heal:${f.id}`)}],['end','조기 철수한다','',c=>{const f=mcEF(c,mcActive);if(f)mcFinish(f,'withdraw');return '부대를 조기 철수시켰다'}]]});
  E('mcInjured',{cat:'용병',need:c=>!!mcEF(c,f=>mcMembers(f).some(x=>x.health<70&&!x.dynMercCaptive)),title:'🩹 부상자의 보상 요구',text:()=>'부상한 대원들이 치료비와 회복할 시간을 요구합니다. 동료들도 회사가 어떻게 대응하는지 지켜보고 있습니다.',o:[['heal','치료비를 지급한다','회사 비용',c=>{const f=mcEF(c);if(!f)return '회사가 이미 정리됐다';return mcAct(c.me,`merc:heal:${f.id}`)}],['bonus','부상자에게 직접 보상한다','회사에서 대원에게 지급',c=>{const f=mcEF(c);if(!f)return '대원들이 이미 떠났다';const xs=mcMembers(f).filter(x=>x.health<70&&!x.dynMercCaptive),sum=Math.min(f.cash,c.wA*xs.length*5);for(const x of xs){const n=sum/Math.max(1,xs.length);f.cash-=n;x.cash+=n}f.merc.morale=cl(f.merc.morale+.1,0,1);return '가용 자금에서 부상 보상금을 지급했다'}]]});
  E('mcCommanderDemand',{cat:'용병',need:c=>!!mcEF(c,f=>f.merc.commander&&mcQuiet(f)),title:'⭐ 지휘관의 독립 요구',text:()=>'이름을 알린 지휘관이 더 나은 대우를 원한다며, 받아들여지지 않으면 회사를 떠나겠다고 합니다.',o:[['reward','공로에 맞게 보상한다','회사 자금 지급',c=>{const f=mcEF(c,f=>!!f.merc.commander),x=f&&S.byId.get(f.merc.commander);if(!f||!x)return '지휘관 자리가 바뀌었다';const n=Math.min(f.cash,c.wA*10);f.cash-=n;x.cash+=n;f.merc.morale=cl(f.merc.morale+.08,0,1);return '지휘관과 처우를 합의했다'}],['release','독립을 허용한다','지휘관 이탈',c=>{const f=mcEF(c,f=>!!f.merc.commander);if(f)mcRelease(f,S.byId.get(f.merc.commander));return '지휘관이 회사를 떠나 자기 길을 택했다'}]]});
  E('mcRegimeChange',{cat:'용병',need:c=>!!mcEF(c,f=>mcActive(f)&&f.merc.contract.paused),title:'🏛️ 새 정권의 계약 확인',text:()=>'고용국의 새 정권이 이전 통치자가 맺은 계약을 계속할 것인지 확인해 달라고 합니다.',o:[['renew','계약을 확인하고 계속한다','',c=>{const f=mcEF(c,f=>mcActive(f)&&f.merc.contract.paused);if(!f)return '이미 결정됐다';return mcAct(c.me,`merc:renew:${f.id}`)}],['leave','정변을 계기로 철수한다','',c=>{const f=mcEF(c,mcActive);if(f)mcFinish(f,'withdraw');return '새 정권과의 계약을 거절하고 철수했다'}]]});
  E('mcVictoryBonus',{cat:'용병',need:c=>!!mcEF(c,f=>f.merc.contract?.status==='victory'&&!f.merc.bonusHandled),title:'🏅 승전 보상 분쟁',text:()=>'승전 계약을 마친 대원들이 성과급을 요구합니다. 회사에는 다음 파견을 준비할 자금도 필요합니다.',o:[['share','대원에게 성과급을 나눈다','회사 현금 일부 분배',c=>{const f=mcEF(c);if(!f)return '회사가 정리됐다';const xs=mcMembers(f),sum=Math.max(0,f.cash)*.15;for(const x of xs){f.cash-=sum/Math.max(1,xs.length);x.cash+=sum/Math.max(1,xs.length)}f.merc.bonusHandled=true;f.merc.morale=cl(f.merc.morale+.1,0,1);return '승전 성과급을 나눴다'}],['reserve','다음 계약을 위해 남긴다','사기 하락',c=>{const f=mcEF(c);if(f){f.merc.bonusHandled=true;f.merc.morale=Math.max(0,f.merc.morale-.1)}return '보상금을 회사 준비금으로 남겼다'}]]});
  E('mcCivilianComplaint',{cat:'용병',need:c=>!!mcEF(c,mcActive),title:'📣 민간인 피해 의혹',text:()=>'부대가 활동한 지역에서 민간인 피해를 호소하는 서한이 왔습니다. 지휘관은 사실 확인이 필요하다고 말합니다.',o:[['investigate','조사와 피해 지원을 시작한다','회사 비용·평판 회복',c=>{const f=mcEF(c);if(!mcEventPay(c,f,c.wA*10))return '지원 자금을 마련하지 못했다';f.merc.reputation=cl(f.merc.reputation+.05,0,1);c.chain('mcInquiry',15,{firm:f.id});return '독립적인 조사와 지원을 시작했다'}],['deny','확인 없이 의혹을 부인한다','계약 신용 하락',c=>{const f=mcEF(c);if(f)f.merc.reputation=Math.max(0,f.merc.reputation-.15);c.rep(-.05);return '해명을 믿지 않는 사람들이 늘었다'},{trait:'honesty'}]]});
