  E('scUnionPressure',{cat:'생활',need:c=>!!scUnion(c.me),title:'📋 노조 활동에 대한 압박',text:()=>'회사 쪽에서 노조 요구를 낮추면 대화하겠다고 제안했습니다. 동료들 사이에서도 의견이 갈립니다.',o:[['talk','동료들과 요구안을 조정한다','',c=>{c.mem.set('scUnionTalk',S.day);return '동료들의 의견을 모아 협상안을 정리했다'}],['strike','파업으로 요구를 전달한다','기존 파업 체계',c=>{const boss=S.byId.get(c.me.emp);if(boss?.strikeUntil>S.day)return '이미 파업 중이다';return scAct(c.me,'social:strike')}]]});
  E('scPublicDebate',{cat:'생활',need:c=>scState().protest!=null&&!!c.G,title:'📣 시위 이후의 토론',text:()=>'노동 조건 개선 요구를 두고 공개 토론이 열렸습니다. 어떤 주장을 앞세울지 의견을 묻습니다.',o:[['facts','임금·근로 조건 자료를 제시한다','평판 상승',c=>{c.rep(.04);return '구체적인 자료로 요구를 설명했다'}],['listen','반대 의견도 듣는다','사회 신뢰 상승',()=>{S.trust=cl((S.trust??.5)+.02,0,1);return '서로의 의견을 듣는 자리가 됐다'}]]});
  E('scExam',{cat:'생활',need:c=>!!c.me.study,title:'📚 시험을 앞둔 밤',text:()=>'시험이 다가왔습니다. 공부에 더 시간을 쓸지, 몸을 쉬게 할지 고민됩니다.',o:[['study','집중해서 공부한다','학업 진척·피로',c=>{if(c.me.study)c.me.study.p+=5;c.me.fat=Math.min(100,c.me.fat+10);return '공부에 몰두해 이해를 넓혔다'}],['rest','충분히 쉰다','피로 회복',c=>{c.me.fat=Math.max(0,c.me.fat-15);return '몸을 쉬게 하고 다음 수업을 준비했다'}]]});
  E('scStudyGroup',{cat:'생활',need:c=>!!c.me.study,who:c=>adA().find(x=>x!==c.me&&x.study),title:'🤝 함께 공부하자는 제안',text:c=>`${c.n(c.x)}이 수업 내용을 함께 정리하자고 제안했습니다.`,o:[['join','공부 모임에 참여한다','학업·관계 상승',c=>{if(c.me.study)c.me.study.p+=3;c.tie(c.x,.1,'학우');return '서로 모르는 부분을 설명하며 공부했다'}],['alone','혼자 공부한다','',c=>{if(c.me.study)c.me.study.p+=1;return '내 속도로 공부했다'}]]});
  E('scTuitionWorry',{cat:'생활',need:c=>!!c.me.study&&c.me.cash<c.wA*20,title:'💰 학비 걱정',text:()=>'학업이 길어지면서 생활비와 수업료가 부담됩니다. 학업을 계속할지 판단할 때입니다.',o:[['continue','당분간 공부를 이어 간다','학업 유지',()=> '생활비를 살피며 공부를 이어 가기로 했다'],['drop','학업을 중단하고 일한다','학력은 현재 단계 유지',c=>scAct(c.me,'social:dropout')]]});
  E('scTravelDetour',{cat:'생활',need:c=>!!scState().trip,title:'🌧️ 여행길의 지연',text:()=>'궂은 날씨로 귀환편이 늦어질 수 있다는 소식이 전해졌습니다. 다른 교통편을 구하면 예정대로 돌아갈 수 있습니다.',o:[['pay','대체 교통편을 구한다','개인 비용',c=>{wfPay(c.me,c.wA*3);return '대체 교통편으로 기존 귀환 일정을 유지했다'}],['wait','사흘 더 머문다','귀환 3일 지연',c=>{const t=scState().trip;if(t){t.until+=3;c.me.dynTravelUntil=t.until}return '현지에서 사흘 더 머물기로 했다'}]]});
  E('scTravelMemory',{cat:'생활',need:c=>scState().trips.length>0,title:'🗺️ 여행에서 얻은 생각',text:()=>'여행에서 본 다른 나라의 생활 방식이 떠오릅니다. 그 경험을 이웃과 나눌 기회가 생겼습니다.',o:[['share','견문을 나눈다','평판 상승',c=>{c.rep(.03);return '다른 나라에서 보고 들은 이야기를 나눴다'}],['write','기록으로 남긴다','',c=>{c.mem.set('scTravelJournal',S.day);c.happy(.02);return '여행기를 써 두었다'}]]});
  E('scFestivalAfter',{cat:'생활',need:c=>scState().festivals>0,title:'🎉 축제가 끝난 뒤',text:()=>'행사를 도운 이웃들이 다음 축제를 위해 어떤 점을 개선하면 좋을지 의견을 보내왔습니다.',o:[['thank','도운 사람들에게 감사를 전한다','사회 신뢰 상승',c=>{c.rep(.02);S.trust=cl((S.trust??.5)+.02,0,1);return '함께 행사를 만든 사람들에게 감사를 전했다'}],['record','의견을 기록한다','',c=>{c.mem.set('scFestivalNotes',S.day);return '다음 축제를 위한 의견을 정리했다'}]]});
  E('scIdentityReaction',{cat:'생활',need:c=>!!c.me.dynIdentityPublic,who:c=>adA().find(x=>x!==c.me),title:'💬 공개 이후의 대화',text:c=>`${c.n(c.x)}이 당신의 정체성 공개 이후 마음이 어떤지 조심스럽게 물었습니다.`,o:[['talk','내 생각을 솔직히 이야기한다','관계 상승',c=>{c.tie(c.x,.1,'솔직한 대화');c.happy(.03);return '서로의 생각을 차분히 나눴다'}],['private','더 이야기하고 싶지 않다고 한다','',()=> '대화의 범위를 정하고 사생활을 존중해 달라고 말했다']]});
  E('scGamblingInvite',{cat:'생활',need:c=>scState().lastGamble!=null&&S.day-scState().lastGamble<YEAR,title:'🎲 다시 가자는 권유',text:()=>'함께 도박장에 갔던 사람이 한 번 더 가자고 권합니다. 지난 결과와 별개로 다시 돈을 잃을 수 있습니다.',o:[['decline','오늘은 가지 않는다','도박 습관 감소',c=>{c.me.gambA=Math.max(0,(c.me.gambA||0)-.08);return '권유를 거절하고 일상으로 돌아갔다'}],['budget','당분간 도박을 쉬겠다고 한다','',c=>{S.dyn.cool.actscgamble=S.day+30;c.me.gambA=Math.max(0,(c.me.gambA||0)-.04);return '한동안 도박장에 가지 않기로 했다'}]]});
  E('scMatchThanks',{cat:'생활',need:c=>scState().matches.length>0,who:c=>{const m=scState().matches.at(-1);return m&&sBy(m.x)},title:'💐 중매의 감사 인사',text:c=>`${c.n(c.x)}이 혼인을 주선해 준 일에 감사를 전해왔습니다.`,o:[['accept','감사 인사를 받는다','관계 상승',c=>{c.tie(c.x,.15,'중매 감사');return '두 사람의 앞날을 축복했다'}],['visit','새 가정을 찾아 축하한다','작은 선물 비용',c=>{if(c.x?.alive){const n=Math.min(Math.max(0,c.me.cash),c.wA*2);c.me.cash-=n;c.x.cash+=n}c.tie(c.x,.2,'혼인 축하');return '새 가정을 찾아 작은 선물을 전했다'}]]});

  // 관계 사건은 같은 성인 인물과의 기억을 이어 간다.
  function rrEventPerson(c,p=()=>true){return rrAll(c.me).filter(r=>!r.ended&&p(r)).map(r=>sBy(r.target)).find(x=>rrEligible(c.me,x))}
  function rrEC(c){return rrEligible(c.me,c.x)?rrGet(c.me,c.x):null}
  E('rrLetterReply',{cat:'관계',need:c=>!!rrEventPerson(c,r=>r.letter&&r.phase<4),who:c=>rrEventPerson(c,r=>r.letter&&r.phase<4),title:'✉️ 답장에 남은 질문',text:c=>`${c.n(c.x)}의 답장에는 당신이 무심코 했던 말이 인용돼 있습니다. “그때 말한 건 어떤 뜻이었어요?” 상대는 당신의 대답을 기다립니다.`,o:[['honest','생각을 솔직히 설명한다','신뢰 상승',c=>{if(rrEC(c))rrRemember(c.me,c.x,'편지 속 질문에 솔직히 답했다',.03,.08);return '말의 뜻을 숨기지 않고 설명했다'}],['listen','상대의 생각부터 묻는다','',c=>{if(rrEC(c))rrRemember(c.me,c.x,'서로의 생각을 먼저 물었다',.04,.05);return '편지가 짧은 안부를 넘어 대화가 됐다'}]]});
  E('rrMeetingQuestion',{cat:'관계',need:c=>!!rrEventPerson(c,r=>r.phase===3),who:c=>rrEventPerson(c,r=>r.phase===3),title:'💬 다음 만남의 의미',text:c=>`${c.n(c.x)}이 조심스럽게 물었습니다. “우리가 다시 만나는 건, 서로에게 어떤 의미인가요?” 가볍게 넘길 수 없는 질문입니다.`,o:[['clear','아직 알아 가는 중이라고 말한다','신뢰 상승',c=>{if(rrEC(c))rrRemember(c.me,c.x,'관계를 서두르지 않겠다고 분명히 말했다',.02,.08);return '상대에게 기대를 부풀리는 대신 현재 마음을 설명했다'}],['ask','관계를 시작할지 정식으로 묻는다','상대의 선택',c=>{return rrEC(c)?rrAct(c.me,'rel:commit:'+c.x.id):'상대와의 관계가 달라졌다'}]]});
  E('rrBrokenPromise',{cat:'관계',chain:1,valid:c=>!!c.x&&rrAll(c.me).some(r=>r.target===c.x.id&&r.promise?.broken&&!r.ended),who:c=>rrEventPerson(c,r=>!!r.promise?.broken),title:'🕰️ 지키지 못한 약속',text:c=>`${c.n(c.x)}이 먼저 연락하지 않은 이유를 묻자 한동안 답이 없었습니다. 이윽고 짧은 말이 돌아왔습니다. “약속한 날에는 기다렸어요.”`,o:[['apologize','변명 없이 사과한다','신뢰 일부 회복',c=>{const r=rrEC(c);if(r){r.promise=null;rrRemember(c.me,c.x,'지키지 못한 약속에 변명 없이 사과했다',.01,.06)}return '기다리게 한 일을 인정하고 사과했다'}],['time','다시 함께할 시간을 낸다','',c=>rrEC(c)?rrAct(c.me,'rel:visit:'+c.x.id+':talk'):'관계가 이미 정리됐다']]});
  E('rrJealousy',{cat:'관계',need:c=>!!rrEventPerson(c,r=>r.jealousy>.15),who:c=>rrEventPerson(c,r=>r.jealousy>.15),title:'🌧️ 말하지 않았던 서운함',text:c=>`${c.n(c.x)}이 다른 사람에게는 쉽게 내는 시간을 왜 자신에게는 내지 못하느냐고 물었습니다. 질투보다 오래 쌓인 서운함에 가까운 말입니다.`,o:[['listen','비교하지 않고 이야기를 듣는다','질투 감소',c=>{const r=rrEC(c);if(r){r.jealousy=Math.max(0,r.jealousy-.15);rrRemember(c.me,c.x,'서운함을 가볍게 넘기지 않고 들었다',.04,.08)}return '상대의 말을 끝까지 들었다'}],['dismiss','대수롭지 않게 넘긴다','신뢰 하락',c=>{if(rrEC(c))rrRemember(c.me,c.x,'서운하다는 말을 대수롭지 않게 넘겼다',-.04,-.1);return '대화가 짧게 끝났고 거리가 생겼다'}]]});
  E('rrQuietMeeting',{cat:'관계',need:c=>!!rrEventPerson(c,r=>r.phase===4),who:c=>rrEventPerson(c,r=>r.phase===4),title:'☕ 잠깐의 일상',text:c=>`${c.n(c.x)}과 마주 앉았지만 이번에는 중요한 부탁도, 다툼도 없습니다. 상대는 당신의 하루가 어땠는지 물었습니다.`,o:[['share','평범한 하루를 이야기한다','애정 상승',c=>{if(rrEC(c))rrRemember(c.me,c.x,'특별한 일 없이 평범한 하루를 나눴다',.08,.04);c.happy(.03);return '평범한 이야기를 나누는 시간이 쌓였다'}],['ask','상대의 하루부터 묻는다','신뢰 상승',c=>{if(rrEC(c))rrRemember(c.me,c.x,'상대의 하루와 걱정을 먼저 물었다',.04,.08);return '당신이 기억하지 못했던 사소한 일들을 들었다'}]]});
  E('rrWitness',{cat:'관계',need:c=>!!c.me.affair&&!!c.me.partner&&wfAdult(sBy(c.me.affair)),who:c=>sBy(c.me.affair),title:'👀 마주친 시선',text:c=>`${c.n(c.x)}과 이야기를 나누던 중 아는 사람이 지나갔습니다. 짧은 인사 뒤에 설명하기 어려운 침묵이 남았습니다. 이 만남이 어디까지 알려질지 알 수 없습니다.`,o:[['prepare','상대와 앞으로의 일을 의논한다','후속 대화',c=>{if(rrEC(c))rrRemember(c.me,c.x,'관계가 알려질 가능성을 함께 의논했다',0,.06);c.me.dynSpouseSuspicion=cl((c.me.dynSpouseSuspicion||0)+.2,0,1);c.chain('rrSpouseTalk',5,{x:c.me.partner});return '말을 맞추기보다 앞으로 감당할 일을 이야기했다'}],['end','관계를 정리한다','정인 관계 종료',c=>{const x=c.x;if(x){x.affair=null;const r=(S.dyn.relationships||{})[c.me.id+':'+x.id];if(r)r.ended=true}c.me.affair=null;return '더 관계를 이어 가지 않기로 했다'}]]});
  E('rrSpouseTalk',{cat:'관계',chain:1,title:'🏠 집에서 기다리던 질문',text:c=>`${c.n(c.x)}이 다른 사람에게서 들은 이야기를 꺼냈습니다. “내가 직접 듣게 해 줄 수는 없었어요?” 대답을 미룰수록 침묵이 무거워집니다.`,o:[['admit','사실을 인정하고 책임을 이야기한다','부부 갈등·후속',c=>{if(rrEligible(c.me,c.x)){rrRemember(c.me,c.x,'숨긴 관계를 인정하고 책임을 이야기했다',-.1,-.12);setRel(c.me,c.x,Math.max(0,(c.me.rel??.5)-.15))}c.chain('rrAfterConfession',10,{x:c.x?.id});return '상처를 인정하고 앞으로의 결정을 함께 이야기하기로 했다'}],['deny','사실을 숨긴다','신뢰 하락',c=>{if(rrEC(c))rrRemember(c.me,c.x,'직접 들은 질문에도 사실을 숨겼다',-.08,-.18);return '대답은 했지만 의심이 사라지지는 않았다'},{trait:'honesty'}]]});
