  E('rrLoverFuture',{cat:'관계',need:c=>!!c.me.affair&&wfAdult(sBy(c.me.affair)),who:c=>sBy(c.me.affair),title:'💌 관계의 미래',text:c=>`${c.n(c.x)}이 다음 약속을 정하다가 말을 멈췄습니다. “계속 이렇게 만날 수 있을까요?” 오늘 하루를 넘어서 관계의 미래를 묻는 말입니다.`,o:[['honest','지킬 수 있는 약속만 이야기한다','신뢰 상승',c=>{if(rrEC(c))rrRemember(c.me,c.x,'지킬 수 있는 약속의 범위를 솔직히 말했다',.02,.08);return '확신하지 못하는 일을 약속하지 않았다'}],['promise','함께할 시간을 약속한다','약속을 지켜야 함',c=>{const r=rrEC(c);if(!r)return '관계가 달라졌다';if(r.promise)return '이미 한 약속부터 지키기로 했다';return rrAct(c.me,'rel:promise:'+c.x.id)}]]});
