    if(op==='refuge'){pay(wA*3);let n=0;for(const a of adA().filter(a=>!a.home).slice(0,12)){a.innDay=S.day;a.health=Math.min(100,a.health+3);n++}rep(.04);return `떠돌이 ${n}명을 ${N}에 재워 줬다`}
    if(op==='free'){pay(wA*5);let n=0;for(const a of S.agents.filter(a=>a.alive&&a.health<60&&(a.w||0)<median()).slice(0,10)){a.health=Math.min(100,a.health+10);n++}rep(.06);ap(.02);return `가난한 환자 ${n}명을 무료로 고쳐 줬다`}
    if(op==='school'){b.school=true;rep(.04);mile('school',`첫 학교. ${josa(nm(me),'이','가')} 회관을 학교로 열었다`,[me.id]);return `${josa(N,'을','를')} 학교로 열었다`}
    if(op==='meet'){rep(.03);if(G&&p2Ruler(me))ap(.03);else for(const x of adA().slice(0,20))if(wr()<.3)dynFamTie(x,.05,'마을 회의');return '마을 회의를 열어 내 뜻을 알렸다'}
    if(op==='release'){const g=me.inv.grain||0;const hun=S.agents.filter(a=>a.alive&&a.hunger>=60);if(g<5||!hun.length)throw Error('풀 곡식이 없거나 굶는 사람이 없습니다');const each=Math.min(g*.8,hun.length*6)/hun.length;for(const a of hun)a.inv.grain=(a.inv.grain||0)+each;me.inv.grain-=each*hun.length;rep(.08);ap(.04);return `곡식을 풀어 ${hun.length}명을 먹였다`}
    if(op==='hoard'){const pr=Math.max(.2,S.price.grain||1),q=Math.floor(wA*10/pr);pay(wA*10);me.inv.grain=(me.inv.grain||0)+q;S.price.grain=pr*1.06;rep(-.04);if(G&&wr()<.2)G.cases.push({t:'hoard',who:me.id,amt:wA*10,ev:.4,d:S.day});return `곡식 ${q}가마를 사재기했다. 곡식값이 들썩인다`}
    if(op==='patrol'){const c=adA().filter(a=>a!==me&&(a.crimes||0)>0&&!((a.jailUntil||0)>S.day)).sort((x,y)=>(y.crimes||0)-(x.crimes||0))[0];if(!c)return '순찰을 돌았지만 잡을 사람이 없었다';c.jailUntil=S.day+YEAR/4;c.caught=(c.caught||0)+1;rep(.04);return `순찰 중에 ${josa(nm(c),'을','를')} 붙잡았다`}
    if(op==='extort'){const g=bdTake(wA*8,me);me.cash+=g;rep(-.06);if(G&&wr()<.25)G.cases.push({t:'extort',who:me.id,amt:g,ev:.5,d:S.day});return `경비원들이 상인들에게서 ${won(g)}을 뜯어 왔다`}
    if(op==='push'){const f=b.firm&&firmById(b.firm);const g=f?coDrain(f,wA*10):bdTake(wA*10,me);if(!f)me.cash+=g;if(wr()<.2){const w=wpick(S.agents.filter(a=>a.alive&&a.emp===me.id));if(w){w.health=Math.max(1,w.health-30);dynFamTie(w,-.2,'공장 사고')}rep(-.03);return `증산으로 ${won(g)}을 더 벌었지만 일꾼이 크게 다쳤다`}return `증산으로 ${won(g)}을 더 벌었다`}
    if(op==='show'){pay(wA*10);const g=bdTake(wA*18,me);me.cash+=g;rep(.04);return `${bdHas(b,'arena')?'대회':'공연'}에 사람이 몰려 표값 ${won(g)}을 벌었다`}
