      if(op==='praise'){rep(.05);ap(.05);if(wr()<.1){rep(-.08);return `${josa(pn,'이','가')} 주인 찬양 기사만 싣는다는 비웃음을 샀다`}return `${pn}에 나를 띄우는 기사를 실었다`}
      if(op==='scoop'){if(wr()<.4){const g=bdTake(wA*12,me);me.cash+=g;rep(.06);return `${josa(pn,'이','가')} 특종을 터뜨렸다. 신문이 불티나게 팔렸다(${won(g)})`}return '취재가 헛걸음이었다'}
      if(op==='tabloid'){b.pk='gossip';b.tabloid=true;const g=bdTake(wA*5,me);me.cash+=g;rep(-.03);return `${josa(pn,'을','를')} 황색 신문으로 바꿨다. 구독이 늘었다`}
      if(op==='serious'){b.pk='watch';b.tabloid=false;rep(.03);return `${josa(pn,'을','를')} 정론지로 바꿨다`}
      if(op==='close'){b.closed=S.day+YEAR*99;return `${josa(pn,'을','를')} 폐간했다`}
