  const adLikes=(x,y)=>x.orient==='bi'||((x.orient||'het')==='hom')===(x.sex===y.sex);
  function adCands(me){return adA().filter(x=>x!==me&&x.id!==me.partner&&!dynKin().has(x.id)&&x.age>=18*YEAR&&x.age<me.age+20*YEAR&&adLikes(me,x)&&adLikes(x,me)&&!x.affair).sort((x,y)=>((y.looks??.5)+(y.g.lib??.5))-((x.looks??.5)+(x.g.lib??.5))).slice(0,5)}
  function adBaby(me,x){if(!wfAdult(me)||!wfAdult(x)||me.sex===x.sex)return null;const F=me.sex==='F'?me:x,M=F===me?x:me;if(F.age>=45*YEAR)return null;const hus=F.partner&&S.byId.get(F.partner);const dad=hus&&hus.sex==='M'?hus:M;const c=mk({sur:dad.sur,family:dad.family,g:childGenome(F.g,M.g),gen:Math.max(F.gen,M.gen)+1,parents:[F.id,dad.id]});c.home=F.home;F.kids.push(c.id);if(dad!==M){dad.kids.push(c.id);M.secretKids=(M.secretKids||[]).concat(c.id);c.secretF=M.id}else M.kids.push(c.id);S.tot.births++;S.yr.births++;S.yr.secretKid=(S.yr.secretKid||0)+(dad!==M?1:0);return c}
  function adBizBld(me,f){return bdMine(me).filter(b=>f.some(x=>bdHas(b,x)))}
