    if(S.trade?.on&&hb.length)add('adult:tour','향락 사업','원정 향락 관광 유치',`이웃 나라 손님을 끌어 큰돈 · 국제 망신 · ${G?.policy?.sexTourBan?'단속법 있음':''}`,W('tour'));
    // 미인계·스캔들
    const tg=adA().filter(wfAdult).filter(x=>x!==me&&!dynKin().has(x.id)).sort((x,y)=>dynScore(y)-dynScore(x)).slice(0,5);
    a=add('adult:honey','미인계·스캔들','미인계',`사람을 붙여 상대를 홀리고 약점을 잡음 · ${won(wA*10)}`,me.cash<wA*10?'돈이 모자람':W('honey'));a.opts=tg.map(x=>['p'+x.id,nm(x)]);
    if(G){const ms=[...p2Mem(),S.byId.get(G.judge)].filter(x=>wfAdult(x)&&x!==me);if(ms.length){a=add('adult:sexbribe','미인계·스캔들','성 접대 로비',`의원·재판관을 술자리로 매수 · 내 편↑ · 폭로되면 미투 스캔들`,W('sexbribe'));a.opts=ms.slice(0,5).map(x=>['p'+x.id,nm(x)])}}
