    if(op==='fling'){cool('fling',15);me.happy=cl((me.happy??.5)+.05,0,1);me.dynStress=Math.max(0,(me.dynStress||0)-15);if(wr()<.08){me.std=1;return '하룻밤을 보냈지만 몹쓸 병이 옮았다'}if(publicFig(me)&&wr()<.15){rep(-.05);return '하룻밤 상대가 소문을 내고 다녔다'}return '낯선 밤을 보냈다. 머리가 한결 가볍다'}
    if(op==='party'){if(me.cash<wA*15)throw Error('돈이 모자랍니다');D.mem={...D.mem,adParty:{v:1,d:S.day,gen:D.gen,ids:[]}};me.cash-=wA*15;SP(me,'family',wA*15);cool('party',60);for(const x of adA().filter(wfAdult).filter(x=>x!==me).sort((x,y)=>dynScore(y)-dynScore(x)).slice(0,4))dynFamTie(x,.15,'향락 파티');if(wr()<.15){scandal(me,'향락 파티',[me.id]);return '파티가 끝나기도 전에 소문이 마을을 덮었다'}return '밤새 이어진 파티로 거물들과 은밀한 사이가 됐다'}
    if(op==='conc'){const x=who();if(!rrEligible(me,x))throw Error('성인 상대가 아닙니다');cool('conc',30);if(wr()>=cl(.35+(x.g.lux??.5)*.3+(x.g.boss??.5)*.2,.1,.9))return `${nm(x)}이 입궁 제안을 거절했다. 상대의 선택을 존중했다`;x.dynConc=me.id;x.home=me.home;dynFamTie(x,.2,'입궁');if(me.partner){const p=S.byId.get(me.partner);if(p){p.happy=cl((p.happy??.5)-.1,0,1)}}dynChron(`${josa(nm(x),'이','가')} ${nm(me)}의 ${me.sex==='F'?'남총':'후궁'}으로 들어오다`,[me.id,x.id]);rrGet(me,x);return `${josa(nm(x),'이','가')} 자신의 의사로 입궁 제안을 받아들였다`}
