    if(op==='mag'){const b=S.bldgs.find(y=>y.id===Number(arg.slice(1)));if(!b||!bdMine(me).includes(b))throw Error('내 건물이 아닙니다');cool('mag',30);b.dynAdultMag=b.dynAdultMag?0:S.day;return b.dynAdultMag?'성인 잡지를 찍기 시작했다':'성인 잡지를 접었다'}
