  function jrOn(){const G=S.gov;return !!(S.dyn&&G&&['indep','semi','puppet'].includes(courtKind()))}
  function jrJ(){const G=S.gov;return (G?.judges||[]).map(j=>S.byId.get(j.id)).filter(x=>x&&x.alive)}
