    for(const f of coMine(me).filter(f=>!f.merc)){const a=add('econ:project:'+f.id,'부동산 개발',`${f.name} · 개발 사업 선택`,'기존 회사 개발 조건·회사 자금·보상금 적용 · 조건 미충족이면 착공 불가',S.sites.some(x=>x.firm===f.id)?'회사 공사가 진행 중':'');a.opts=Object.entries(EC_PROJECT).map(([k,n])=>[k,n])}
