    const workshop=S.shops.some(x=>x.owner===me.id&&x.cond>.2);for(const item of ['tool','jewel','furn'])add('econ:craft:'+item,'공방·생산',`${EC_GOODS[item]} 제작`,'공방·재료 필요 · 제작 후 보유 물품에 반영 · 시장에 직접 판매 가능',!workshop?'내 공방이 없음':item==='jewel'&&!me.knowJewel?'장신구 제작 기술이 없음':dynWait('eccraft'));
    for(const item of ['wood','plank','gold','tool','jewel','furn','grain','iron']){const a=add('econ:market:'+item,'물품 거래',`${EC_GOODS[item]||item} 직접 매매`,`시세 ${won(S.price[item]||0)} · 보유 ${(me.inv[item]||0).toFixed(1)} · 실제 주민과 거래`,'');a.opts=[['buy','최대 5개 매입'],['sell','최대 5개 판매']]}
